<script setup>
import { computed,onMounted,ref } from 'vue'
import { api } from './api'
import VariableInsert from './VariableInsert.vue'
import HttpBodyBuilder from './HttpBodyBuilder.vue'
const items=ref([]),fields=ref([]),loading=ref(false),error=ref(''),editing=ref(null),testResult=ref(null),testing=ref(false),search=ref(''),status=ref('all')
const creatingField=ref(false),fieldSaving=ref(false),fieldError=ref(''),mappingForField=ref(null)
const newField=ref({label:'',key:'',field_type:'text'})
const blank=()=>({name:'',description:'',method:'POST',endpoint_url:'',headers:[],query:[],cookies:[],body_type:'json',body:{},response_mappings:[],timeout_seconds:15,active:true})
const filtered=computed(()=>items.value.filter(x=>(status.value==='all'||(status.value==='active'?x.active:!x.active))&&(!search.value||x.name.toLowerCase().includes(search.value.toLowerCase())||x.endpoint_url.toLowerCase().includes(search.value.toLowerCase()))))
const responsePaths=computed(()=>testResult.value?.response_paths||[])
function fmt(v){return v?new Intl.DateTimeFormat(undefined,{day:'numeric',month:'short',year:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(v)):'—'}
async function load(){loading.value=true;error.value='';try{items.value=await api.httpApis()}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadFields(){try{fields.value=await api.contactFields()}catch{fields.value=[]}}
function addRow(key){editing.value[key].push({key:'',value:''})}function removeRow(key,i){editing.value[key].splice(i,1)}
function addMapping(source_path=''){editing.value.response_mappings.push({source_path,target_key:''})}function removeMapping(i){editing.value.response_mappings.splice(i,1)}function mapWholeResponse(){addMapping('$')}
function insertRowVariable(row,token){row.value=String(row.value||'')+token}function insertEndpointVariable(token){editing.value.endpoint_url=String(editing.value.endpoint_url||'')+token}
function rawBodyText(){return typeof editing.value?.body==='string'?editing.value.body:JSON.stringify(editing.value?.body??{},null,2)}
function setRawBody(value){editing.value.body=value}function insertRawVariable(token){editing.value.body=rawBodyText()+token}
function normalizeBody(){if(['json','form'].includes(editing.value.body_type)&&(!editing.value.body||typeof editing.value.body!=='object'||Array.isArray(editing.value.body))){try{const parsed=JSON.parse(editing.value.body||'{}');editing.value.body=parsed&&typeof parsed==='object'&&!Array.isArray(parsed)?parsed:{}}catch{editing.value.body={}}}if(editing.value.body_type==='none')editing.value.body=null;if(editing.value.body_type==='raw'&&typeof editing.value.body!=='string')editing.value.body=JSON.stringify(editing.value.body??{},null,2)}
function create(){editing.value=blank();testResult.value=null}function edit(x){editing.value=JSON.parse(JSON.stringify(x));editing.value.response_mappings=editing.value.response_mappings||[];testResult.value=null}
async function save(){error.value='';try{const saved=editing.value.id?await api.updateHttpApi(editing.value.id,editing.value):await api.createHttpApi(editing.value);editing.value=saved;await load();return saved}catch(e){error.value=e.message;return null}}
async function test(){testing.value=true;testResult.value=null;try{const saved=await save();if(!saved?.id){testResult.value={success:false,error:error.value||'Unable to save API before testing'};return}testResult.value=await api.testHttpApi(saved.id);await load()}catch(e){testResult.value={success:false,error:e.message}}finally{testing.value=false}}
async function remove(x){if(!confirm(`Delete “${x.name}”?`))return;await api.deleteHttpApi(x.id);await load()}
function slugKey(value){return String(value||'').toLowerCase().trim().replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'').replace(/^[^a-z]+/,'')}
function openFieldCreator(mapping=null){mappingForField.value=mapping;fieldError.value='';newField.value={label:'',key:'',field_type:'text'};creatingField.value=true}
function fieldLabelChanged(){if(!newField.value.key)newField.value.key=slugKey(newField.value.label)}
function closeFieldCreator(){creatingField.value=false;mappingForField.value=null;fieldError.value=''}
async function createMappingField(){fieldError.value='';const label=String(newField.value.label||'').trim(),key=slugKey(newField.value.key);if(!label||!key){fieldError.value='Field name and key are required.';return}fieldSaving.value=true;try{const created=await api.createContactField({label,key,field_type:newField.value.field_type||'text',required:false,active:true,sort_order:100,options:[]});await loadFields();if(mappingForField.value)mappingForField.value.target_key=created?.key||key;closeFieldCreator()}catch(e){fieldError.value=e.message}finally{fieldSaving.value=false}}
onMounted(()=>{load();loadFields()})
</script>
<template>
<section class="http-page"><header><div><p class="eyebrow">Integrations</p><h1>HTTP APIs</h1><p>Connect and manage reusable outbound HTTP APIs for flows and automations.</p></div><button class="primary" @click="create">＋ Create API</button></header><div v-if="error" class="error">{{error}}</div>
<template v-if="!editing"><div class="toolbar"><select v-model="status"><option value="all">Any status</option><option value="active">Active</option><option value="inactive">Inactive</option></select><input v-model="search" placeholder="Search APIs…"><button @click="load">↻ Refresh</button></div><div class="card"><div v-if="loading" class="empty">Loading…</div><div v-else-if="!filtered.length" class="empty">No HTTP APIs yet. Create your first reusable integration.</div><table v-else><thead><tr><th>API name</th><th>Method</th><th>Verified</th><th>Total calls</th><th>Success</th><th>Error</th><th>Last called</th><th>Actions</th></tr></thead><tbody><tr v-for="x in filtered" :key="x.id"><td><strong>{{x.name}}</strong><small>{{x.endpoint_url}}</small></td><td><span class="method">{{x.method}}</span></td><td><span :class="['verified',x.verified?'yes':'no']">{{x.verified?'✓ Verified':'Not verified'}}</span></td><td>{{x.total_calls}}</td><td>{{x.total_success}}</td><td>{{x.total_error}}</td><td>{{fmt(x.last_called_at)}}</td><td><button @click="edit(x)">✎</button><button class="danger" @click="remove(x)">×</button></td></tr></tbody></table></div></template>
<template v-else><button class="back" @click="editing=null">← Back to HTTP APIs</button><div class="editor-grid"><main>
<section class="card form-card"><h2>API Details</h2><p>Enter the basic connection information for the API.</p><div class="details"><label>API Name<input v-model="editing.name" placeholder="e.g. Register customer"></label><label>Method<select v-model="editing.method"><option v-for="m in ['GET','POST','PUT','PATCH','DELETE']" :key="m">{{m}}</option></select></label><label class="url">Endpoint URL<input v-model="editing.endpoint_url" placeholder="https://api.example.com/v1/resource"><VariableInsert :fields="fields" @insert="insertEndpointVariable"/></label></div></section>
<section class="card form-card"><h2>Request Data</h2><p>Configure headers, query parameters, cookies and request body.</p><div v-for="group in ['headers','query','cookies']" :key="group" class="pairs"><div class="pair-head"><strong>{{group.charAt(0).toUpperCase()+group.slice(1)}}</strong><button @click="addRow(group)">＋ Add</button></div><div v-for="(row,i) in editing[group]" :key="i" class="pair"><input v-model="row.key" placeholder="Key"><div class="value-with-variable"><input v-model="row.value" placeholder="Value / %variable%"><VariableInsert :fields="fields" @insert="token=>insertRowVariable(row,token)"/></div><button @click="removeRow(group,i)">×</button></div></div>
<div class="body"><label>Body Type<select v-model="editing.body_type" @change="normalizeBody"><option value="none">None</option><option value="json">JSON</option><option value="form">Form URL Encoded</option><option value="raw">Raw / Text</option></select></label><HttpBodyBuilder v-if="['json','form'].includes(editing.body_type)" v-model="editing.body" :fields="fields" :body-type="editing.body_type"/><label v-else-if="editing.body_type==='raw'">Raw Body<textarea :value="rawBodyText()" @input="setRawBody($event.target.value)" placeholder="Raw request body"></textarea><VariableInsert :fields="fields" @insert="insertRawVariable"/></label><div v-else class="no-body">This request will be sent without a body.</div></div></section>
<section class="card form-card"><div class="test-head"><div><h2>Test & Verify</h2><p>The current form is saved automatically before each test request.</p></div><button class="primary" :disabled="testing" @click="test">{{testing?'Sending…':'Send Test Request'}}</button></div><div v-if="testResult" :class="['response',testResult.success?'ok':'bad']"><div class="response-meta"><span v-if="testResult.status_code"><strong>Status</strong> {{testResult.status_code}}</span><span v-if="testResult.method"><strong>Method</strong> {{testResult.method}}</span><span v-if="testResult.duration_ms!=null"><strong>Duration</strong> {{testResult.duration_ms}} ms</span><span v-if="testResult.content_type"><strong>Content-Type</strong> {{testResult.content_type}}</span></div><div v-if="testResult.requested_url" class="response-url"><strong>Requested</strong> {{testResult.requested_url}}</div><div v-if="testResult.final_url" class="response-url"><strong>Final URL</strong> {{testResult.final_url}}</div><div v-if="testResult.error" class="response-error">{{testResult.error}}</div><pre>{{testResult.response_json?JSON.stringify(testResult.response_json,null,2):(testResult.response||'')}}</pre></div><div v-else class="response">Response will appear here after test…</div></section>
</main><aside><section class="card form-card"><h2>Automation</h2><p>This saved API becomes selectable from any WhatsApp or Telegram HTTP Request flow block.</p><label>Timeout (seconds)<input v-model.number="editing.timeout_seconds" type="number" min="1" max="120"></label><label class="check"><input v-model="editing.active" type="checkbox"> Active</label><button class="save" @click="save">Save API</button></section>
<section class="card form-card mapping-card"><div class="mapping-head"><div><h2>Response Mapping</h2><p>Save values or the complete JSON response into contact custom fields.</p></div><div class="mapping-actions"><button @click="openFieldCreator()">＋ Custom Field</button><button @click="addMapping()">＋ Add</button></div></div><div v-if="testResult?.success" class="root-map"><div><strong>$ · Entire response</strong><span>Useful for arrays and JSON objects consumed by Dynamic Lists.</span></div><button @click="mapWholeResponse">＋ Map entire response</button></div><div v-if="!editing.response_mappings.length" class="mapping-note">Run a successful JSON test, then map a response field — or use <code>$</code> to save the complete JSON response.</div><div v-for="(m,i) in editing.response_mappings" :key="i" class="mapping-row"><label>Response field<input v-model="m.source_path" list="response-paths" placeholder="e.g. $ or data.customer.id"><small v-if="m.source_path==='$'">Entire JSON response</small><small v-else-if="responsePaths.find(p=>p.path===m.source_path)">Sample: {{responsePaths.find(p=>p.path===m.source_path)?.preview}}</small></label><span>→</span><label>Custom field key<div class="field-target"><input v-model="m.target_key" list="field-keys" placeholder="e.g. product_catalog"><button type="button" title="Create custom field" @click="openFieldCreator(m)">＋</button></div></label><button class="mapping-delete" @click="removeMapping(i)">×</button></div><datalist id="response-paths"><option v-for="p in responsePaths" :key="p.path" :value="p.path">{{p.path==='$'?'Entire response':p.preview}}</option></datalist><datalist id="field-keys"><option v-for="f in fields" :key="f.id" :value="f.key">{{f.label}}</option></datalist><div v-if="testResult?.success&&responsePaths.length" class="discovered"><strong>{{responsePaths.length}} response paths available</strong><span><code>$</code> selects the complete response.</span></div><button v-if="editing.response_mappings.length" class="save mappings-save" @click="save">Save Mappings</button></section></aside></div></template>
<div v-if="creatingField" class="field-modal-bg" @click.self="closeFieldCreator"><form class="field-modal" @submit.prevent="createMappingField"><div class="field-modal-head"><div><p class="eyebrow">RESPONSE MAPPING</p><h2>Add Custom Field</h2></div><button type="button" @click="closeFieldCreator">×</button></div><p>Create a reusable subscriber field without leaving the HTTP API.</p><div v-if="fieldError" class="error">{{fieldError}}</div><label>Field name<input v-model="newField.label" required maxlength="120" placeholder="Product Catalog" @input="fieldLabelChanged"></label><label>Variable / key<input v-model="newField.key" required pattern="[a-z][a-z0-9_]*" placeholder="product_catalog"><small>Available as %{{newField.key||'field_key'}}%</small></label><label>Field type<select v-model="newField.field_type"><option value="text">Text / JSON</option><option value="textarea">Textarea</option><option value="email">Email</option><option value="number">Number</option><option value="date">Date</option><option value="checkbox">Checkbox</option></select></label><footer><button type="button" class="secondary" @click="closeFieldCreator">Cancel</button><button class="primary" type="submit" :disabled="fieldSaving">{{fieldSaving?'Creating…':'Create Field'}}</button></footer></form></div>
</section>
</template>
<style scoped>
.http-page{margin-left:220px;padding:34px 38px;min-height:100vh;background:#f4f7f6;color:#17251e}.http-page>header{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:24px}.http-page h1{font-size:30px;margin:2px 0 5px}.http-page header p:last-child,.form-card>p,.mapping-head p{margin:0;color:#74867e}.eyebrow{text-transform:uppercase;color:#119052;font-size:11px;font-weight:800;letter-spacing:.08em;margin:0}.primary,.save{border:0;background:#168fd0;color:#fff;border-radius:9px;padding:11px 15px;font-weight:800;cursor:pointer}.secondary{border:1px solid #cedbd5;background:#fff;border-radius:8px;padding:9px 12px;cursor:pointer}.toolbar{display:flex;gap:12px;margin-bottom:16px}.toolbar input{flex:1}.toolbar input,.toolbar select,.toolbar button,input,select,textarea{border:1px solid #d6e1db;background:#fff;border-radius:9px;padding:11px 12px}.toolbar select{min-width:180px}.card{background:#fff;border:1px solid #dce5df;border-radius:14px;overflow:hidden}.empty{padding:60px;text-align:center;color:#7c8c84}table{width:100%;border-collapse:collapse}th,td{padding:14px 16px;border-bottom:1px solid #e9efec;text-align:left}th{font-size:11px;text-transform:uppercase;color:#819088;background:#f8faf9}td small{display:block;color:#84928b;margin-top:4px;max-width:320px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}td button{border:1px solid #d8e2dd;background:#fff;border-radius:7px;padding:6px 9px;margin-right:5px}.danger{color:#b32f2f}.method{font-weight:800;color:#2773a0}.verified{font-size:11px;font-weight:800}.verified.yes{color:#07944d}.verified.no{color:#8b9691}.back{margin-bottom:15px;border:1px solid #d4dfda;background:#fff;border-radius:8px;padding:9px 12px}.editor-grid{display:grid;grid-template-columns:minmax(0,1fr) 370px;gap:18px}.editor-grid main,.editor-grid aside{display:flex;flex-direction:column;gap:18px}.form-card{padding:22px}.form-card h2{margin:0 0 5px;font-size:18px}.details{display:grid;grid-template-columns:1fr 150px;gap:12px;margin-top:18px}.details .url{grid-column:1/-1}label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:700;color:#53645b}label input,label select{font-weight:400;color:#17251e}.pairs{margin-top:20px}.pair-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.pair-head button,.mapping-head button{border:1px solid #b9d9ca;background:#fff;border-radius:7px;padding:6px 9px}.pair{display:grid;grid-template-columns:1fr 1.5fr 38px;gap:8px;margin-bottom:8px;align-items:start}.pair>button{border:0;background:#fff0f0;color:#b33;border-radius:8px;height:42px}.value-with-variable>input{width:100%;box-sizing:border-box}.value-with-variable :deep(.variable-insert){margin-top:4px}.body{display:grid;gap:10px;margin-top:22px;padding-top:18px;border-top:1px solid #e8efeb}.body textarea{min-height:150px;font-family:ui-monospace,monospace}.no-body{padding:18px;border-radius:9px;background:#f5f8f7;color:#788880}.test-head,.mapping-head{display:flex;justify-content:space-between;align-items:center;gap:10px}.mapping-actions{display:flex;gap:6px}.response{margin-top:16px;padding:16px;background:#f3f6f8;border-radius:9px;min-height:80px;overflow:auto}.response.ok{background:#edfaf2}.response.bad{background:#fff0f0}.response-meta{display:flex;gap:18px;flex-wrap:wrap;font-size:12px;margin-bottom:10px}.response-url{font-size:12px;overflow-wrap:anywhere;margin:5px 0}.response-error{color:#a22;font-weight:700;margin:10px 0}.response pre{margin:14px 0 0;white-space:pre-wrap;font-family:ui-monospace,monospace;font-size:12px}.check{flex-direction:row;align-items:center;margin:15px 0}.check input{width:auto}.save{width:100%;background:#16a05c}.mapping-note{margin-top:14px;padding:12px;background:#f4f8f6;border-radius:8px;color:#64756c}.root-map{margin-top:14px;padding:12px;border:1px solid #b9dfcd;background:#eefaf4;border-radius:9px;display:flex;align-items:center;justify-content:space-between;gap:10px}.root-map strong,.root-map span,.discovered strong,.discovered span{display:block}.root-map span,.discovered span{font-size:11px;color:#6b8075;margin-top:3px}.root-map button{white-space:nowrap;border:1px solid #9fd0b7;background:#fff;border-radius:7px;padding:7px 9px;font-weight:700;color:#137347}.mapping-row{display:grid;grid-template-columns:minmax(0,1fr) 20px minmax(0,1fr) 32px;gap:7px;align-items:center;margin-top:13px}.mapping-row input{width:100%;box-sizing:border-box}.mapping-row small{font-weight:400;color:#829188;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.mapping-row>span{text-align:center}.field-target{display:grid;grid-template-columns:minmax(0,1fr) 34px;gap:5px}.field-target button{border:1px solid #b9d9ca;background:#eefaf4;color:#137347;border-radius:7px;font-weight:800;cursor:pointer}.mapping-delete{height:35px;border:0;border-radius:7px;background:#fff0f0;color:#b33}.discovered{margin-top:14px;padding:11px;border-radius:8px;background:#eef8fc}.mappings-save{margin-top:14px}.error{padding:11px 13px;background:#fff0f0;color:#a22;border-radius:8px;margin-bottom:15px}.field-modal-bg{position:fixed;inset:0;background:#0b241b88;z-index:500;display:grid;place-items:center}.field-modal{width:min(460px,92vw);background:#fff;border-radius:14px;padding:22px;box-shadow:0 20px 70px #0003}.field-modal-head{display:flex;justify-content:space-between;align-items:start}.field-modal-head h2{margin:0}.field-modal-head button{border:0;background:none;font-size:24px;cursor:pointer}.field-modal>p{color:#74867e;margin:7px 0 18px}.field-modal label{margin:13px 0}.field-modal label input,.field-modal label select{box-sizing:border-box;width:100%}.field-modal label small{color:#7a8b82}.field-modal footer{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}@media(max-width:1100px){.editor-grid{grid-template-columns:1fr}}@media(max-width:760px){.http-page{margin-left:0;padding:18px}.details,.pair{grid-template-columns:1fr}.pair>button{width:42px}.mapping-actions{flex-direction:column}}
</style>